import subprocess,json,shlex,sys,datetime
from pathlib import Path
m=json.loads(Path('docs/research/local_return_feedback_portable_launch.json').read_text());index=int(sys.argv[1]) if len(sys.argv)>1 else 0;w=m['workers'][index]
code="""import sys,json,platform,hashlib\nfrom pathlib import Path\nr=Path('/work/ring_repo');sys.path[:0]=[str(r),str(r/'scripts')]\nimport torch,numpy\nimport local_return_feedback_portable_run as runner\nimport local_return_feedback_evaluate as evaluator\ntorch.set_num_threads(2);before=evaluator.global_rng_snapshot();cfg=json.loads((r/'models/gc100/gc100_lstm_s1_1000M.json').read_text());streams=runner.feedback.TrialStreams(runner.TRAIN_SEED);start=streams.snapshot();plan=streams.draw(32,runner.feedback.STAGE,cfg);end=streams.snapshot();assert runner.tree_equal(before,evaluator.global_rng_snapshot())\nrng=lambda s:{k:hashlib.sha256(v.numpy().tobytes()).hexdigest() for k,v in s['generators'].items()}\nprint(json.dumps({'scope':'Separate fresh private generator only; no live learner state read or changed; no policy/env/optimizer','seed':runner.TRAIN_SEED,'contexts':32,'stage':plan['stage'],'tensor_schema':evaluator.tensor_schema(plan),'rng_before':rng(start),'rng_after':rng(end),'global_rng_preserved':True,'torch':str(torch.__version__),'numpy':numpy.__version__,'cpu_capability':torch.backends.cpu.get_cpu_capability(),'machine':platform.machine(),'processor':platform.processor(),'threads':torch.get_num_threads()}))\n"""
r=subprocess.run(['gcloud','compute','ssh',w['name'],'--project',m['project'],'--zone',w['zone'],'--quiet','--command','/usr/bin/python3 -c '+shlex.quote(code)],capture_output=True,text=True,timeout=90)
if r.returncode:print(r.stderr[-1000:]);raise SystemExit(r.returncode)
d=json.loads(r.stdout);d['name']=w['name'];d['utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();p=Path('results/local_return_feedback_design/portable/cloud_audit')/(w['name']+'_private_first_plan.json');p.write_text(json.dumps(d,indent=2)+'\n');print(json.dumps({'path':str(p),'cpu_capability':d['cpu_capability'],'global_rng_preserved':d['global_rng_preserved'],'tensors':len(d['tensor_schema'])}))
